def S(N):
    """Calculates the sum S(N) = sum_{a=1}^N sum_{b=1}^N floor((a*b)/(N+1))."""
    sum_val = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            sum_val += (a * b) // (N + 1)
    return sum_val

def f(N):
    """Calculates the target value f(N) = (N^3 - N^2 + 2) / 4."""
    return (N**3 - N**2 + 2) / 4

N_values = [5, 6, 7]
results = {}

for N in N_values:
    s_n = S(N)
    f_n = f(N)
    results[N] = {
        "S(N)": s_n,
        "f(N)": f_n
    }

for N, res in results.items():
    print(f"--- N = {N} ---")
    print(f"S({N}) = {res['S(N)']}")
    print(f"f({N}) = {res['f(N)']}")
    is_equal = res['S(N)'] == res['f(N)']
    print(f"S({N}) == f({N})? {is_equal}")
